package mrpapermoon.whisper.contacts.dbimport androidx.room.TypeConverterimport mrpapermoon.whisper.entity.UserColorimport mrpapermoon.whisper.entity.UserIcon@Suppress("unused")class RoomTypeConverters {	@TypeConverter	fun serialize(icon: UserIcon): Int = icon.ordinal	@TypeConverter	fun deserializeUserIcon(value: Int): UserIcon = UserIcon.entries[value]	@TypeConverter	fun serialize(color: UserColor): Int = color.ordinal	@TypeConverter	fun deserializeUserColor(value: Int): UserColor = UserColor.entries[value]}